<script setup>
import {reactive,ref,computed} from 'vue';
import {RiArrowUpSLine,RiArrowDownSLine} from '@remixicon/vue';
import {useTemplateContext} from './useTemplateContext';
import {cloneApplicationSample} from './applicationSamples';
import * as f from './fixtures';
import DemoBoundary from './DemoBoundary.vue';
import './demo.css';
const props=defineProps({kind:String,version:{type:String,default:'current'}});
const organization=cloneApplicationSample({...f.organization,banner_color:'#e8edff',metrics:{...f.organization.metrics,datasets:1,dataservices:1,reuses:1},permissions:{}});
const api=cloneApplicationSample({...f.dataservice,owner:null,organization,contact_points:[],availability:99.9,rate_limiting:'100 appels par minute',deleted_at:null,archived_at:null,metrics:{...f.dataservice.metrics,reuses:1,discussions:1},description:'## À quoi sert cette API ?\n\nConsultez les indicateurs démographiques des communes françaises et intégrez-les dans vos services.\n\n## Données disponibles\n\n- Code et nom de la commune\n- Population municipale\n- Année de référence'});
const reuse=cloneApplicationSample({...f.reuse,organization,owner:null,metrics:{...f.reuse.metrics,discussions:1},description:'Cette visualisation permet de comparer la population et les évolutions des communes françaises. Elle utilise les données ouvertes de l’Observatoire des territoires.',tags:['population','communes','visualisation']});
const subject=computed(()=>props.kind==='dataservice'?api:props.kind==='reuse'?reuse:organization);
const plural=computed(()=>({dataservice:'dataservices',reuse:'reuses',organization:'organizations'}[props.kind]));
const root=computed(()=>`/${plural.value}/${subject.value.id}`);
const route=reactive({path:root.value,fullPath:root.value,query:{},params:{id:subject.value.id,did:api.id,rid:reuse.id,oid:organization.id},hash:'',name:'entity-template'});
const C=useTemplateContext(props,route);
const tabs=computed(()=>props.kind==='dataservice'?[{key:'information',label:'Informations',suffix:''},{key:'reuses',label:'Réutilisations',suffix:'/reuses',count:1},{key:'discussions',label:'Discussions',suffix:'/discussions',count:1}]:props.kind==='reuse'?[{key:'description',label:'Description',suffix:''},{key:'discussions',label:'Discussions',suffix:'/discussions',count:1}]:[{key:'datasets',label:'Jeux de données',suffix:'/datasets',count:1},{key:'dataservices',label:'API',suffix:'/dataservices',count:1},{key:'reuses',label:'Réutilisations',suffix:'/reuses',count:1},{key:'information',label:'Informations',suffix:'/information'}]);
const active=ref(tabs.value[0].key),search=ref(''),sort=ref('popular'),openProperties=ref(false),openSwagger=ref(false);
const links=computed(()=>tabs.value.map(t=>({...t,href:root.value+t.suffix})));
route.path=links.value[0].href;route.fullPath=route.path;
function clickTab(event){const href=event.target.closest('a')?.getAttribute('href');const tab=links.value.find(l=>l.href===href);if(!tab)return;event.preventDefault();active.value=tab.key;route.path=href;route.fullPath=href;}
function preventNavigation(event){if(event.target.closest('a'))event.preventDefault();}
const visibleItem=computed(()=>{const item=active.value==='datasets'?f.dataset:active.value==='dataservices'?api:reuse;return !search.value.trim()||item.title.toLocaleLowerCase('fr').includes(search.value.trim().toLocaleLowerCase('fr'));});
</script>
<template>
 <div class="demo-content entity-template" @click.capture="preventNavigation"><DemoBoundary :name="kind+'-template'"><Suspense><template #default><div>
  <component :is="C['cdata/SiteHeader/SiteHeader']" />
  <component v-if="kind==='organization'" :is="C['cdata/Organizations/OrganizationBanner']" :organization="organization"><component :is="C['cdata/Breadcrumb/Breadcrumb']"><component :is="C['cdata/Breadcrumbs/BreadcrumbItem']" to="/">Accueil</component><component :is="C['cdata/Breadcrumbs/BreadcrumbItem']" to="/organizations">Organisations</component><component :is="C['cdata/Breadcrumbs/BreadcrumbItem']">{{organization.name}}</component></component></component>
  <div v-else class="container"><div class="mt-4 flex gap-4 flex-wrap items-center justify-between"><component :is="C['cdata/Breadcrumb/Breadcrumb']"><component :is="C['cdata/Breadcrumbs/BreadcrumbItem']" to="/">Accueil</component><component :is="C['cdata/Breadcrumbs/BreadcrumbItem']" :to="'/'+plural">{{kind==='dataservice'?'API':'Réutilisations'}}</component><component :is="C['cdata/Breadcrumbs/BreadcrumbItem']">{{subject.title}}</component></component><component :is="C['cdata/FollowButton']" :url="`/api/1/${plural}/${subject.id}/followers/`" /></div></div>
  <component :is="C.LoadingBlock" status="success" :data="subject">
   <template v-if="kind==='organization'"><div class="container relative"><div class="size-20 bg-white p-1 border border-gray-default rounded-sm -mt-10 -mb-10 relative z-20"><component :is="C.OrganizationLogo" :organization="organization" size-class="size-full" /></div></div><div class="container pt-14 pb-6"><h1 class="text-2xl font-extrabold text-gray-title mb-2.5"><component :is="C.OrganizationNameWithCertificate" :organization="organization" :show-acronym="true" :show-type="false" color-class="text-gray-title" size="xl" /></h1><component :is="C.OwnerType" type="public-service" size="base" color="gray" /><component :is="C.ReadMore" :wanted-height="100" class="mt-2.5 text-sm"><component :is="C.MarkdownViewer" :content="organization.description" :min-heading="3" /></component></div></template>
   <div v-else-if="kind==='reuse'" class="container py-10"><div class="grid md:grid-cols-12 gap-4 items-center"><div class="md:col-span-5"><div class="flex items-center gap-2"><component :is="C.OrganizationLogo" :organization="organization" size-class="size-8" /><component :is="C.OrganizationNameWithCertificate" :organization="organization" as="h2" /></div><h1 class="text-2xl font-extrabold text-gray-title mb-1">{{reuse.title}}</h1><component :is="C.ReuseDetails" :reuse="reuse" /><component :is="C.BrandedButton" :href="reuse.url" new-tab size="xs" class="mt-6">Voir la réutilisation</component></div><img :src="reuse.image" :alt="''" class="md:col-span-7 w-full object-contain max-h-[400px]" /></div></div>
   <template v-else><div class="container pt-3 pb-8"><div class="flex flex-col md:flex-row md:gap-10 items-start"><div class="flex-1 min-w-0"><h1 class="text-2xl font-extrabold text-gray-title mb-6">{{api.title}}</h1><component :is="C.ReadMore" :wanted-height="360"><component :is="C.MarkdownViewer" :content="api.description" :min-heading="3" size="md" /></component></div><aside class="w-full shrink-0 md:w-[384px] space-y-5"><dl class="pl-0"><dt class="font-bold">Producteur</dt><dd class="m-0 p-0"><component :is="C['cdata/OrganizationOwner']" :organization="organization" as="h2" /></dd></dl><section><h2 class="text-base font-bold">Conditions d’accès</h2><dl class="pl-0"><component :is="C['cdata/AccessTypes/AccessTypePanel']" :object="api" hide-access-label /></dl></section><section><h2 class="text-base font-bold">Qualité des métadonnées</h2><component :is="C.DataserviceQuality" :quality="api.quality" /></section><section><h2 class="text-base font-bold">Caractéristiques techniques</h2><dl class="pl-0 space-y-3"><div><dt class="font-bold">URL de base de l’API</dt><dd class="m-0 p-0 break-all"><a class="link" :href="api.base_api_url">{{api.base_api_url}}</a></dd></div><div><dt class="font-bold">Limite d’appels</dt><dd class="m-0 p-0">{{api.rate_limiting}}</dd></div><div><dt class="font-bold">Taux de disponibilité</dt><dd class="m-0 p-0">{{api.availability}} %</dd></div></dl><component :is="C.BrandedButton" color="secondary" size="sm" class="mt-4" @click="openSwagger=!openSwagger">Swagger</component></section></aside></div></div><div class="container space-y-4 mb-8"><component :is="C.SimpleBanner" type="primary-frame"><button class="w-full flex items-center justify-between text-left font-bold text-lg min-h-[42px]" :aria-expanded="openProperties" @click="openProperties=!openProperties">Données renvoyées <component :is="openProperties?RiArrowUpSLine:RiArrowDownSLine" class="size-6" aria-hidden="true" /></button><component v-if="openProperties" :is="C['cdata/OpenApi/OpenApiProperties']" :url="api.machine_documentation_url" :title="api.title" /></component><component :is="C.SimpleBanner" type="primary-frame"><button class="w-full flex items-center justify-between text-left font-bold text-lg min-h-[42px]" :aria-expanded="openSwagger" @click="openSwagger=!openSwagger">Documentation Swagger <component :is="openSwagger?RiArrowUpSLine:RiArrowDownSLine" class="size-6" aria-hidden="true" /></button><component v-if="openSwagger" :is="C['OpenApiViewer/OpenApiViewer']" :url="api.machine_documentation_url" /></component></div></template>
   <div @click="clickTab"><component :is="C['cdata/FullPageTabs/FullPageTabs']" :links="links"><form v-if="kind==='organization'" @submit.prevent><label for="template-org-search" class="sr-only">Rechercher dans l’organisation</label><input id="template-org-search" v-model="search" type="search" class="p-3 bg-transparent text-sm" placeholder="Rechercher dans l’organisation" /></form></component></div>
   <div class="bg-white py-5"><div class="container space-y-5">
    <component v-if="active==='discussions'" :is="C['cdata/Discussions/DiscussionsList']" :subject="subject" :type="kind==='dataservice'?'Dataservice':'Reuse'" />
    <template v-else-if="kind==='reuse'"><section class="grid md:grid-cols-12 gap-6"><div class="md:col-span-9"><h2 class="text-sm uppercase mb-2.5">Description</h2><component :is="C.MarkdownViewer" :content="reuse.description" :min-heading="3" /></div><dl class="md:col-span-3 p-0 space-y-4"><div><dt class="font-bold">Thématique</dt><dd class="m-0">Société</dd></div><div><dt class="font-bold">Type</dt><dd class="m-0">Visualisation</dd></div><div><dt class="font-bold">Mots clés</dt><dd class="m-0 flex flex-wrap gap-1"><span v-for="tag in reuse.tags" :key="tag" class="text-xs px-2 py-1 rounded-xl bg-gray-default">{{tag}}</span></dd></div><div><dt class="font-bold">Dernière mise à jour</dt><dd class="m-0"><component :is="C.FormattedDate" :date="reuse.last_modified" /></dd></div></dl></section><h2 class="text-xl font-bold">Jeux de données utilisés</h2><component :is="C.DatasetCard" :dataset="f.dataset" /></template>
    <template v-else-if="kind==='dataservice'&&active==='information'"><h2 class="text-sm uppercase font-bold">1 jeu de données associé</h2><component :is="C.DatasetCard" :dataset="f.dataset" /><component :is="C['cdata/SectionCollapse']" title="Informations techniques" button-text="Voir les informations techniques"><dl class="p-4"><dt>Identifiant</dt><dd class="m-0">{{api.id}}</dd><dt>Dernière mise à jour</dt><dd class="m-0"><component :is="C.FormattedDate" :date="api.metadata_modified_at" /></dd></dl></component></template>
    <template v-else-if="kind==='organization'&&active==='information'"><h2 class="text-xl font-bold">Statistiques générales</h2><div class="grid md:grid-cols-3 gap-4"><component :is="C.StatBox" title="Jeux de données" :data="f.stats" type="bar" :summary="1" /><component :is="C.StatBox" title="API" :data="f.stats" type="bar" :summary="1" /><component :is="C.StatBox" title="Réutilisations" :data="f.stats" type="bar" :summary="1" /></div></template>
    <template v-else><div v-if="kind==='organization'" class="flex flex-wrap items-center justify-between gap-4"><p class="text-sm font-bold m-0">{{visibleItem?'1 résultat':'Aucun résultat'}}</p><label class="flex items-center gap-2 text-sm">Trier par :<select v-model="sort" class="fr-select"><option value="popular">Popularité</option><option value="recent">Dernière mise à jour</option></select></label></div><template v-if="visibleItem"><component v-if="active==='datasets'" :is="C.DatasetCard" :dataset="f.dataset" /><component v-else-if="active==='dataservices'" :is="C.DataserviceCard" :dataservice="api" /><component v-else :is="C.ReuseCard" :reuse="reuse" :organization-url="null" /></template><p v-else>Aucun résultat ne correspond à votre recherche.</p></template>
   </div></div>
  </component>
  <component :is="C['cdata/SiteFooter/SiteFooter']" />
 </div></template><template #fallback><p class="container py-8">Chargement de la page…</p></template></Suspense></DemoBoundary></div>
</template>
<style scoped>.entity-template{background:white;min-height:100vh}.entity-template :deep(.container){max-width:1200px;margin-inline:auto;padding-inline:24px}</style>
